//! The audiomon record icon, drawn in code so the tray icon and the exe/installer icon
//! (generated by build.rs) come from one definition and no image files are shipped.
//! Same world as the phone app: black vinyl, a navy label, a gold rim.
//! Also compiled into build.rs via `#[path]`, so it depends on nothing but std.

/// Subsamples per axis for anti-aliased edges.
const SS: u32 = 4;

const VINYL: [u8; 3] = [0x0E, 0x0E, 0x10];
const GROOVE: [u8; 3] = [0x2A, 0x2A, 0x30];
/// Light outer edge so the black disc stays visible on a dark taskbar.
const EDGE: [u8; 3] = [0x6A, 0x6A, 0x72];
const LABEL: [u8; 3] = [0x1C, 0x25, 0x47];
const GOLD: [u8; 3] = [0xD9, 0xA4, 0x41];
const IDLE_LABEL: [u8; 3] = [0x4A, 0x4D, 0x56];
const IDLE_RIM: [u8; 3] = [0x9A, 0x9C, 0xA4];

/// Live: navy label with a gold rim (streaming, and the app icon). Idle: greyed label.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Style {
    Live,
    Idle,
}

/// Straight RGBA pixels (`size * size * 4`, top row first) of the record on transparent.
pub fn record_rgba(size: u32, style: Style) -> Vec<u8> {
    let px = 2.0 / size as f32; // one pixel in unit coordinates (-1..1 across)
    let (label, rim) = match style {
        Style::Live => (LABEL, GOLD),
        Style::Idle => (IDLE_LABEL, IDLE_RIM),
    };
    // Thin features never drop below about a pixel, so small sizes stay legible.
    let edge_w = (0.05f32).max(1.0 * px);
    let rim_w = (0.045f32).max(1.0 * px);
    let grooves = size >= 48;
    let hole = size >= 24;

    let mut rgba = vec![0u8; (size * size * 4) as usize];
    for y in 0..size {
        for x in 0..size {
            let mut acc = [0f32; 4];
            for sy in 0..SS {
                for sx in 0..SS {
                    let u = (x as f32 + (sx as f32 + 0.5) / SS as f32) * px - 1.0;
                    let v = (y as f32 + (sy as f32 + 0.5) / SS as f32) * px - 1.0;
                    let r = (u * u + v * v).sqrt();
                    let color = if r > 0.97 {
                        continue;
                    } else if r > 0.97 - edge_w {
                        EDGE
                    } else if r > 0.58 {
                        // Grooves: fine rings across the vinyl.
                        if grooves && ((r - 0.62) / 0.06).fract() < 0.22 && r < 0.88 { GROOVE } else { VINYL }
                    } else if hole && r < 0.07 {
                        VINYL
                    } else if r > 0.50 - rim_w / 2.0 && r < 0.50 + rim_w / 2.0 {
                        rim
                    } else {
                        label
                    };
                    acc[0] += color[0] as f32;
                    acc[1] += color[1] as f32;
                    acc[2] += color[2] as f32;
                    acc[3] += 1.0;
                }
            }
            if acc[3] > 0.0 {
                let i = ((y * size + x) * 4) as usize;
                // Average the covered subsamples' colour; coverage becomes alpha.
                rgba[i] = (acc[0] / acc[3]) as u8;
                rgba[i + 1] = (acc[1] / acc[3]) as u8;
                rgba[i + 2] = (acc[2] / acc[3]) as u8;
                rgba[i + 3] = (acc[3] * 255.0 / (SS * SS) as f32) as u8;
            }
        }
    }
    rgba
}
